import {ContractError,ApiError} from './cloud-contract.mjs';
import {attendanceId} from './attendance-contract.mjs';
import {validMonth} from './monthly-contract.mjs';
import {draftRecord,salaryRecord} from './payroll-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const workbookMime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
export function confirmationRecord(r){attendanceId(r?.id);attendanceId(r.member_id);attendanceId(r.draft_id);validMonth(r.month);if(!['confirm','reopen'].includes(r.action)||!Number.isSafeInteger(r.revision)||r.revision<1||typeof r.note!=='string'||typeof r.actor_name!=='string'||!Number.isFinite(Date.parse(r.created_at)))throw new ContractError();if(r.previous_id!==null)attendanceId(r.previous_id);return r;}
export function confirmationDetail(r){confirmationRecord(r);if(r.action==='confirm'){if(!r.snapshot||r.snapshot.month!==r.month||r.snapshot.member?.id!==r.member_id)throw new ContractError();draftRecord(r.snapshot.draft);salaryRecord(r.snapshot.salary);if(r.snapshot.draft.id!==r.draft_id)throw new ContractError();}else if(r.snapshot!==null)throw new ContractError();return r;}
export function confirmationHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();v.rows.forEach(confirmationRecord);return v;}
export function confirmationPayload(v){const keys=['requestKey','memberId','month','action','expectedDraftId','expectedConfirmationId','note','confirmed'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||!['confirm','reopen'].includes(v.action)||typeof v.note!=='string'||!v.note.trim()||v.note.length>2000||v.confirmed!==true)throw new ContractError('请填写原因并确认本次操作。');attendanceId(v.requestKey);attendanceId(v.memberId);attendanceId(v.expectedDraftId);if(v.expectedConfirmationId!==null)attendanceId(v.expectedConfirmationId);validMonth(v.month);return {...v,note:v.note.trim()};}
export function exportable(v){validMonth(v?.month);if(!Array.isArray(v.rows))throw new ContractError();for(const r of v.rows){attendanceId(r.member?.id);if(typeof r.member.name!=='string'||typeof r.ready!=='boolean')throw new ContractError();if(r.confirmation!==null)confirmationRecord(r.confirmation);if(r.ready&&(r.confirmation?.action!=='confirm'||!Number.isSafeInteger(r.totalCents)||r.totalCents<0))throw new ContractError();}return v;}
export function exportPayload(v){if(!v||Object.keys(v).some(k=>!['requestKey','month','confirmationIds'].includes(k))||!Array.isArray(v.confirmationIds)||!v.confirmationIds.length||v.confirmationIds.length>100||new Set(v.confirmationIds).size!==v.confirmationIds.length)throw new ContractError('请选择有效的工资确认范围。');attendanceId(v.requestKey);validMonth(v.month);v.confirmationIds.forEach(attendanceId);return v;}
export async function readWorkbook(response){if(!response.ok)throw new ApiError(response.status,'工资表下载失败，请重新核对导出记录。');if(response.headers.get('content-type')?.split(';')[0]!==workbookMime)throw new ContractError('导出文件类型不正确。');const id=attendanceId(response.headers.get('x-studio-export-id')),hash=response.headers.get('x-studio-file-hash');if(!/^[a-f0-9]{64}$/.test(hash||''))throw new ContractError();const blob=await response.blob();if(blob.size<4||blob.size>5*1024*1024)throw new ContractError('导出文件大小不正确。');const bytes=new Uint8Array(await blob.slice(0,4).arrayBuffer());if(bytes[0]!==80||bytes[1]!==75||bytes[2]!==3||bytes[3]!==4)throw new ContractError('导出文件内容不正确。');if(globalThis.crypto?.subtle){const digest=new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),actual=[...digest].map(n=>n.toString(16).padStart(2,'0')).join('');if(actual!==hash)throw new ContractError('文件校验不一致，请重新下载。');}return {id,blob,fileHash:hash};}
